<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\RepairMaintenanceRecord;use Illuminate\Http\Request;
class RepairMaintenanceRecordController extends Controller{public function index(Request $r){$q=RepairMaintenanceRecord::with(['vehicle','driver'])->where('is_deleted',false);if($r->filled('search')){$s=$r->search;$q->where(fn($x)=>$x->where('job_order_no','like',"%$s%")->orWhere('invoice_no','like',"%$s%"));}return response()->json(['success'=>true,'data'=>$q->latest('job_date')->paginate($r->integer('per_page',25))]);}public function show(RepairMaintenanceRecord $repairMaintenanceRecord){return response()->json(['success'=>true,'data'=>$repairMaintenanceRecord->load(['vehicle','driver'])]);}public function store(Request $r){return response()->json(['success'=>true,'data'=>RepairMaintenanceRecord::create($this->data($r)+['job_order_no'=>'JO-'.now()->format('Y').'-'.str_pad(RepairMaintenanceRecord::count()+1,4,'0',STR_PAD_LEFT)])],201);}public function update(Request $r,RepairMaintenanceRecord $repairMaintenanceRecord){$repairMaintenanceRecord->update($this->data($r));return response()->json(['success'=>true,'data'=>$repairMaintenanceRecord]);}public function destroy(RepairMaintenanceRecord $repairMaintenanceRecord){$repairMaintenanceRecord->update(['is_deleted'=>true]);return response()->json(['success'=>true]);}private function data(Request $r){return $r->validate(['vehicle_id'=>'required|exists:vehicles,id','driver_id'=>'nullable|exists:drivers,id','job_date'=>'required|date','job_type'=>'required|string|max:80','priority'=>'required|string|max:20','work_status'=>'required|string|max:30','completed_date'=>'nullable|date','service_provider'=>'nullable|string|max:150','contact_person'=>'nullable|string|max:150','provider_phone'=>'nullable|string|max:50','invoice_no'=>'nullable|string|max:80','subtotal'=>'nullable|numeric|min:0','sales_tax'=>'nullable|numeric|min:0','discount'=>'nullable|numeric|min:0','total_paid'=>'nullable|numeric|min:0','payment_method'=>'nullable|string|max:50','description'=>'required|string','parts'=>'nullable|array','next_service_date'=>'nullable|date','next_service_odometer'=>'nullable|integer','notes'=>'nullable|string']);}}
